function persist(next,{replace=false}={}){
 if(!replace&&writeBlocked){storageError='Saved progress needs attention. Export the existing data or import a valid backup in 家长中心.';return false;}
 try{if(!replace&&localStorage.getItem(STORAGE_KEY)!==savedRaw){writeBlocked=true;storageError='Progress changed in another tab. Reload this page before continuing.';return false;}}catch{}
 state=next;
 try{const result=saveState(localStorage,state,content);if(result?.ok===false)throw Error(result.error);savedRaw=localStorage.getItem(STORAGE_KEY);writeBlocked=false;storageError='';return true;}catch{storageError='Progress could not be saved. Keep this tab open and export a backup in 家长中心.';return true;}
}
