function homePage(){const ls=lessons().filter(l=>!l.library);return `<div class="map-heading"><div class="map-top"><p class="eyebrow">YOUR LEARNING MAP</p><span class="map-top-actions"><button class="secondary print-entry" data-action="print-pick" lang="zh-CN"><span aria-hidden="true">🖨</span> 打印练习题</button><button class="ghost intro-replay" data-action="intro">▶ Watch the intro</button></span></div><h1 class="page-title">${state.activeChildId==='B'?'What shall we look at today?':'What shall we learn today?'}</h1><p class="muted">${state.activeChildId==='A'?'Year 4 foundations + Year 5 ideas':'Year 3 ideas'} · every year is open.</p></div>${todayPlanPanel()}${stickerCard()}${curriculum.years.length?`<section class="library-entry panel"><h2>Choose a year</h2>${yearPicker()}</section>${linesEntry()}`:''}${ls.length?`<section class="knowledge-collection"><div class="section-heading"><h2>${state.activeChildId==='A'?'Fraction lessons: one part, several parts, the whole':'Fraction lessons: equal parts on a number line'}</h2></div><div class="topic-grid">${ls.map(topicTile).join('')}</div></section>`:''}`;}
// Today's plan: a short warm-up from work already waiting, then one thing to learn. It suggests an order only.
const startYear=()=>state.activeChildId==='B'?3:5;
function todayPlan(){const id=state.activeChildId,mine=lessons(),cur=sheetData.sheets[id],open=cur&&!cur.finished?cur:null,answered=s=>s.itemIds.filter(i=>String(s.drafts?.[i]??'').trim()).length;
 const dueReviews=renderDue.filter(r=>mine.some(l=>l.id===r.lessonId)).map(r=>({lessonId:r.lessonId,title:r.lesson.title_en,dueDate:r.dueDate,questions:r.items.length}));
 const by=new Map();for(const m of mistakeList().filter(m=>!m.fixed)){if(!mine.some(l=>l.id===m.lesson.id))continue;const g=by.get(m.lesson.id)||{lessonId:m.lesson.id,title:m.lesson.title_en,count:0,lastSeq:0};g.count++;g.lastSeq=Math.max(g.lastSeq,m.last.seq);by.set(m.lesson.id,g);}
 const path=[];for(let y=startYear();y<=8;y++)for(const l of curriculumLessons(y))path.push({lessonId:l.id,title:cards.find(c=>c.lessonId===l.id)?.title_en||l.title_en,size:setSize(l),practised:practisedTopic(l),started:!!savedSheet(l.id)||attempts(l.id).length>0||state.exposures.some(e=>e.childId===id&&e.lessonId===l.id)});
 const currentSheet=open&&mine.some(l=>l.id===open.lessonId)?{lessonId:open.lessonId,title:allLessons().find(l=>l.id===open.lessonId)?.title_en||'Your practice',kind:open.kind==='mistakes'?'mistakes':'practice',answered:answered(open),total:open.itemIds.length}:null;
 return buildTodayPlan({dueReviews,openMistakes:[...by.values()],currentSheet,path,perQuestionSeconds:PER_QUESTION[id]});}
function todayPlanPanel(){const plan=todayPlan(),doneToday=state.attempts.filter(a=>a.childId===state.activeChildId&&a.day===today()).length,q=n=>`${n} question${n===1?'':'s'}`;
 const row=s=>{const [label,detail,button]=s.kind==='review'?['Remember it?',`${q(s.questions)} from another day · ${esc(s.title)}`,`<button class="primary" data-review="${s.lessonId}">Start</button>`]
  :s.kind==='fix'?['Fix tricky questions',`${q(s.questions)} · ${esc(s.title)}`,`<button class="primary" data-mistakes="${s.lessonId}" data-fix-limit="${FIX_LIMIT}">Fix</button>`]
  :s.kind==='finish-fix'?['Finish fixing',`${q(s.questions)} left · ${esc(s.title)}`,'<button class="primary" data-action="resume-sheet">Continue</button>']
  :s.kind==='continue'?['Finish your practice',`${esc(s.title)} · ${s.answered} of ${s.total} done`,'<button class="primary" data-action="resume-sheet">Continue</button>']
  :[s.kind==='keep-going'?'Keep going':'Learn something new',`${topicOf(s.lessonId)?esc(topicOf(s.lessonId).title_en)+' · ':''}${esc(s.title)}`,`<button class="primary" data-knowledge="${s.lessonId}">Open</button>`];
  return `<li class="today-step" data-today="${s.kind}"><span class="today-text"><strong>${label}</strong><span>${detail}</span><small>About ${s.minutes} min</small></span>${button}</li>`;};
 return `<section class="today-plan" aria-labelledby="today-title"><div class="today-head"><h2 id="today-title">Today’s plan</h2>${plan.steps.length?`<span class="today-time">About ${plan.minutes} min</span>`:''}</div>${doneToday?`<p class="today-done">✓ ${q(doneToday)} answered today. Well done!</p>`:''}${plan.steps.length?`<ol class="today-steps">${plan.steps.map(row).join('')}</ol>`:'<p class="muted">Nothing waiting right now. Pick any year below.</p>'}${plan.moreToTry?'<p class="today-more"><button class="ghost" data-action="review">More to try again</button></p>':''}</section>`;}
function relatedLinks(links,label){if(!links?.length)return '';return `<div class="knowledge-links"><h3>${label}</h3>${links.map(r=>{const l=lessons().find(l=>l.kp_id===r.kpId);return `<div><span class="small">${r.relation==='required'?(label.startsWith('Build')?'Foundation':'Builds on this card'):'Related idea'}</span>${l?`<button class="secondary" data-knowledge="${l.id}">${esc(r.label_en)}</button>`:`<p>${esc(r.label_en)}</p>`}</div>`;}).join('')}</div>`;}
let visuals=[],learnView={lessonId:null,frame:0,phase:'picture',choice:null};
const visualFor=id=>visuals.find(v=>v.lessonId===id);
// The one way into practice: continue an unfinished set, otherwise start a new set of 20.
function practiceButton(l){const s=savedSheet(l.id);if(s&&!s.finished){const n=s.itemIds.filter(id=>String(s.drafts?.[id]??'').trim()).length;return `<button class="primary" data-resume-lesson="${l.id}">Continue my practice · ${n} of ${s.itemIds.length} done</button>`;}return '<button class="primary" data-action="start-sheet">Start practice · 20 questions</button>';}
function lastResults(l){return savedSheet(l.id)?.finished?`<div class="lesson-choice"><button class="ghost" data-resume-lesson="${l.id}">See my last results</button></div>`:'';}
const motionLesson=()=>lessons().find(l=>l.id===knowledgeId);
function learningSteps(current){return `<ol class="learning-steps" aria-label="Learning journey">${['Look','Practise'].map((label,i)=>`<li class="${current===i?'current':''}" ${current===i?'aria-current="step"':''}><span>${i+1}</span>${label}</li>`).join('')}</ol>`;}
// Progress on each topic tile, for the child using the app now.
function topicStatus(l){const m=mastered(l).status,set=savedSheet(l.id),open=mistakeList(state.activeChildId,l.id).filter(x=>!x.fixed).length;let main;
 if(m==='retained')main=['star','★★ Remembered'];else if(m==='independent')main=['star','★ Got it'];
 else if(set?.finished){const right=set.itemIds.filter(id=>state.attempts.find(a=>a.id===set.submitted?.[id])?.correct).length;main=['done',`Practised · ${right}/${set.itemIds.length}`];}
 else if(set){const n=set.itemIds.filter(id=>String(set.drafts?.[id]??'').trim()).length;main=['busy',`Practice started · ${n}/${set.itemIds.length}`];}
 else if(attempts(l.id).length||state.exposures.some(e=>e.childId===state.activeChildId&&e.lessonId===l.id))main=['seen','Started'];else main=['new','New'];
 return `<span class="topic-status ${main[0]}">${main[1]}</span>${open?`<span class="topic-status fix">${open} to fix</span>`:''}`;}
const practisedTopic=l=>['independent','retained'].includes(mastered(l).status)||!!savedSheet(l.id)?.finished;
function topicTile(l,step=0){const v=visualFor(l.id),k=cards.find(c=>c.lessonId===l.id);return `<button class="knowledge-tile topic-tile" data-knowledge="${l.id}">${step?`<span class="step-no" aria-label="Step ${step}">${step}</span>`:''}${v?`<img class="topic-thumb" src="./${esc(v.frames[0].image)}" alt="" width="120" height="80" loading="lazy">`:''}<span class="topic-text"><span class="topic-title">${esc(k?.title_en||l.title_en)}</span><span class="topic-meta">${l.library?'':`<span class="topic-status year">Year ${l.scope_id.slice(1)}</span>`}${topicStatus(l)}</span></span></button>`;}
// A topic card groups 1–5 lessons (its steps) so the year page stays short; every step is still its own lesson.
function topicCard(t,ls){const steps=t.lessonIds.map(id=>ls.find(l=>l.id===id)).filter(Boolean),done=steps.filter(practisedTopic).length,fix=steps.reduce((n,l)=>n+mistakeList(state.activeChildId,l.id).filter(x=>!x.fixed).length,0);
 return `<section class="topic-card ${done===steps.length?'all-done':done?'part-done':''}" data-topic="${t.id}" aria-label="${esc(t.title_en)}"><header class="topic-card-head"><h3>${esc(t.title_en)}</h3><span class="topic-card-meta">${steps.length===1?'1 step':`${done} of ${steps.length} steps`}${fix?` · <span class="topic-status fix">${fix} to fix</span>`:''}</span>${steps.length>1?`<span class="progress-bar small" aria-hidden="true"><span style="width:${Math.round(done/steps.length*100)}%"></span></span>`:''}</header><ol class="topic-steps">${steps.map((l,i)=>`<li>${topicTile(l,steps.length>1?i+1:0)}</li>`).join('')}</ol></section>`;}
// Idea lines: one idea from Year 3 to Year 8, one lesson a year (dist/lines.mjs). The child's place on a
// line is the first step from their starting year that is not practised yet. A line suggests an order only.
let lineId=null,knowledgeFrom=null;
const lineLesson=id=>lessons().find(l=>l.id===id);
const lineStatus=line=>{const start=startYear(),practised=id=>{const l=lineLesson(id);return !!l&&practisedTopic(l);},next=nextStepIndex(line,{startYear:start,practised}),done=line.lessonIds.filter(practised).length;return {start,practised,next,done,steps:line.lessonIds.length};};
function lineDots(line,s){return `<span class="line-dots" aria-hidden="true">${line.lessonIds.map((id,i)=>`<span class="line-dot ${s.practised(id)?'done':i===s.next?'next':yearOf(id)<s.start?'below':''}" title="Year ${yearOf(id)}"></span>`).join('')}</span>`;}
function lineChip(line){const s=lineStatus(line),next=s.next<0?null:lineLesson(line.lessonIds[s.next]);return `<button class="line-chip" data-line="${line.id}" aria-label="${esc(line.title_en)}: ${s.done} of ${s.steps} steps practised${next?`, next Year ${yearOf(next.id)}`:''}"><span class="line-chip-title">${esc(line.title_en)}</span>${lineDots(line,s)}<small>${next?`Next: Year ${yearOf(next.id)}`:s.done?'Every step practised':`Year ${yearOf(line.lessonIds[0])}–${yearOf(line.lessonIds.at(-1))}`}</small></button>`;}
// The home page stays short: six chips, the lines this child has started first; the rest are one tap away.
const HOME_LINES=6;
function linesEntry(){const started=new Set(LINES.filter(l=>lineStatus(l).done>0).map(l=>l.id)),shown=[...LINES.filter(l=>started.has(l.id)),...LINES.filter(l=>!started.has(l.id))].slice(0,HOME_LINES);return `<section class="lines-entry panel" aria-labelledby="lines-entry-title"><div class="section-heading"><h2 id="lines-entry-title">Follow an idea</h2><button class="secondary" data-action="lines">All ${LINES.length} ideas</button></div><p class="muted">The same idea, one step a year from Year 3 to Year 8. Finished adding in Year 3? Go straight on to adding in Year 4.</p><div class="line-chips">${shown.map(lineChip).join('')}</div></section>`;}
function linesPage(){return `<div class="lesson-header"><button class="ghost" data-action="home">Back to my learning map</button></div><p class="eyebrow">FOLLOW AN IDEA</p><h1 class="page-title">One idea, year by year</h1><p class="muted">Each line follows one idea from Year 3 to Year 8, one lesson a year. When a step feels easy, go on to the next year. Stuck? Step back one. The order is a suggestion, not a lock.</p><div class="line-cards">${LINES.map(line=>{const s=lineStatus(line),next=s.next<0?null:lineLesson(line.lessonIds[s.next]);return `<section class="line-card ${s.next<0&&s.done?'all-done':s.done?'part-done':''}" aria-label="${esc(line.title_en)}"><header class="line-card-head"><h3>${esc(line.title_en)}</h3><span class="topic-card-meta">${s.done} of ${s.steps} steps</span></header>${lineDots(line,s)}<p class="line-next">${next?`Next: <strong>Year ${yearOf(next.id)}</strong> · ${esc(next.title_en)}`:s.done?'Every step practised. Well done!':''}</p><div class="home-actions">${next?`<button class="primary" data-knowledge="${next.id}" data-from-line="${line.id}">Open the next step</button>`:''}<button class="secondary" data-line="${line.id}">See the whole line</button></div></section>`;}).join('')}</div>`;}
function linePage(){const line=lineById(lineId);if(!line)return linesPage();const s=lineStatus(line);
 const step=(id,i)=>{const l=lineLesson(id),y=yearOf(id),st=stepOf(id),isNext=i===s.next,prev=i>0?lineLesson(line.lessonIds[i-1]):null;if(!l)return '';
  return `<li class="line-step ${isNext?'next':''} ${s.practised(id)?'done':''}" data-line-step="${id}"><span class="line-year">Year ${y}${y<s.start&&!s.practised(id)?'<small>Before your start</small>':''}</span><div class="line-step-body">${isNext?'<span class="line-next-label">Next on this line</span>':''}${topicTile(l)}${st&&st.count>1?`<p class="small muted line-step-topic">Part of “${esc(st.topic.title_en)}” in Year ${y} (step ${st.index+1} of ${st.count}). <button class="ghost inline" data-year="${y}" data-open-domain="${esc(st.topic.domain)}">See the other steps</button></p>`:''}${isNext&&prev?`<p class="small muted">Stuck? Step back to <button class="ghost inline" data-knowledge="${prev.id}" data-from-line="${line.id}">Year ${yearOf(prev.id)}: ${esc(prev.title_en)}</button></p>`:''}</div></li>`;};
 return `<div class="lesson-header"><button class="ghost" data-action="lines">All ideas</button></div><p class="eyebrow">FOLLOW AN IDEA</p><h1 class="page-title">${esc(line.title_en)}</h1><div class="library-progress"><span>${s.steps} steps, Year ${yearOf(line.lessonIds[0])} to Year ${yearOf(line.lessonIds.at(-1))} · ${s.done} practised</span><span class="progress-bar" aria-hidden="true"><span style="width:${Math.round(s.done/s.steps*100)}%"></span></span></div><ol class="line-steps">${line.lessonIds.map(step).join('')}</ol><p class="small muted">Practised means a finished practice set or an independent check. Going on to the next year is always allowed; stepping back is always fine.</p>`;}
