 const heading=`<div class="lesson-header"><button class="ghost" data-action="home">Back to my learning</button><span class="badge ${l.scope_id==='y4'?'yellow':'green'}">Year ${l.scope_id.slice(1)} · ${s.review?'Revisit':l.mode==='reinforce'?'Keep it strong':'Explore'}</span></div>`;
