 const i=s.items[s.index],worked=i.stage==='worked',sol=s.showSolution||(worked&&l.mode!=='reinforce'),stage={entry:'Warm up',worked:'Let’s work one out',guided:'Try it together',independent:'Your turn',review:'A fresh look'}[i.stage];
