const printedBefore=(childId,lessonId)=>{try{return JSON.parse(localStorage.getItem(PRINT_KEY)||'{}')[childId+':'+lessonId]||[];}catch{return [];}};
function rememberPrinted(){try{const all=JSON.parse(localStorage.getItem(PRINT_KEY)||'{}'),k=state.activeChildId+':'+printView.lessonId;all[k]=[...new Set([...(all[k]||[]),...printView.itemIds])].slice(-400);localStorage.setItem(PRINT_KEY,JSON.stringify(all));}catch{}}
function openPrint(lessonId,fresh=false){const l=allLessons().find(x=>x.id===lessonId);if(!l)return;if(fresh)rememberPrinted();const prior=[...printedBefore(state.activeChildId,lessonId),...state.attempts.filter(a=>a.childId===state.activeChildId).map(a=>a.itemId)];let sel;try{sel=deepLesson(l)?selectDeepSet(l,prior):selectPracticeItems(l,20,prior);}catch{notice='这一课的练习题不够打印一组。';render();return;}printView={...printView,lessonId,itemIds:sel.items.map(i=>i.id),deep:deepLesson(l),from:fresh?printView.from:view==='print-pick'?'pick':'lesson'};view='print';session=null;notice='';render();window.scrollTo(0,0);}
function printQuestion(i,n){const note=i.diagram_note_en||i.representation?.diagram_note_en,answer=i.choices?`<div class="pq-options">${i.choices.map(c=>`<span><b class="pq-ring"></b>${esc(c)}</span>`).join('')}</div>`:i.answer_spec.op==='compare_fractions'?`<div class="pq-options pq-signs">${['&lt;','=','&gt;'].map(c=>`<span><b class="pq-ring"></b>${c}</span>`).join('')}</div>`:`<div class="pq-answer"><span>Answer</span><span class="pq-line"></span></div>`;
 return `<article class="pq" data-print-question="${i.id}"><div class="pq-head"><span class="pq-num">${n+1}</span><p>${esc(i.prompt_en)}</p></div>${note?`<p class="pq-note">${esc(note)}</p>`:''}${questionPicture(i,'pq-diagram')}${answer}</article>`;}
// Printing is for the grown-up: a clear button at the top of each lesson, and a lesson chooser from the home page.
function printTopButton(l){return `<button class="secondary print-top" data-print="${l.id}" lang="zh-CN"><span aria-hidden="true">🖨</span> 打印 / 存 PDF</button>`;}
let printYear=null;
function printPickPage(){const id=state.activeChildId,yr=printYear||startYear(),ls=lessons().filter(l=>Number(l.scope_id.slice(1))===yr),pilot=ls.filter(l=>!l.library),lib=ls.filter(l=>l.library),domains=[...new Set(lib.map(l=>l.domain))],btn=l=>`<button class="secondary" data-print="${l.id}">${esc(l.title_zh||l.title_en)}<small>${esc(l.title_en)}</small></button>`;
 const suggest=[];const next=todayPlan().steps.find(s=>['continue','keep-going','new'].includes(s.kind));if(next)suggest.push(next.lessonId);for(const e of [...state.attempts,...state.exposures].filter(e=>e.childId===id).sort((a,b)=>b.seq-a.seq)){if(suggest.length>=6)break;if(e.lessonId&&!suggest.includes(e.lessonId))suggest.push(e.lessonId);}
 const sl=suggest.map(x=>lessons().find(l=>l.id===x)).filter(Boolean);
 return `<div class="lesson-header"><button class="ghost" data-action="home">返回首页</button></div><p class="eyebrow">打印练习题</p><h1 class="page-title">选一课来打印</h1><p class="muted">每课一组 20 题，可以附答案页，Mac 和 iPad 都可以存成 PDF。打印的题不计入学习记录。</p>${sl.length?`<section class="panel print-pick"><h2>${esc(child().name||id)} 最近学的和接下来要学的</h2><div class="notes-links">${sl.map(btn).join('')}</div></section>`:''}<section class="panel print-pick"><h2>按年级找</h2><div class="notes-years" role="group" aria-label="选择年级">${[3,4,5,6,7,8].map(y=>`<button class="${y===yr?'primary':'secondary'}" data-print-year="${y}" aria-pressed="${y===yr}">Year ${y}</button>`).join('')}</div>${pilot.length?`<h3>分数小课</h3><div class="notes-links">${pilot.map(btn).join('')}</div>`:''}${topicGroups(lib,yr,btn,'h3')}</section>`;}
function printPage(){const l=allLessons().find(x=>x.id===printView.lessonId);if(!l)return '<p>找不到这一课。</p>';const items=printView.itemIds.map(id=>l.items.find(i=>i.id===id)).filter(Boolean),v=visualFor(l.id);
 return `<div class="print-tools" lang="zh-CN"><div class="home-actions">${printView.from==='pick'?'<button class="ghost" data-action="print-pick">返回选课</button>':`<button class="ghost" data-knowledge="${l.id}">返回这一课</button>`}<button class="primary" data-action="do-print">打印 / 存为 PDF</button><button class="secondary" data-action="print-new">换一组题</button></div><div class="print-opts"><label><input type="checkbox" data-print-opt="answers" ${printView.answers?'checked':''}> 最后一页附答案（给家长）</label><label><input type="checkbox" data-print-opt="pictures" ${printView.pictures?'checked':''}> 开头附三张讲解图</label></div><p class="small muted">点“打印 / 存为 PDF”后：Mac 上在打印窗口左下角选“存储为 PDF”；iPad 上点分享按钮可以存到“文件”。打印的题不计入学习记录。下面是打印出来的样子。</p></div>
 <div class="print-doc"><header class="pd-head"><div class="pd-brand">${brand()}</div><div class="pd-name"><span>Name <i></i></span><span>Date <i></i></span></div></header><h1 class="pd-title">${esc(l.title_en)}</h1><p class="pd-sub">Year ${l.scope_id.slice(1)} · ${items.length} questions${printView.deep?' in three parts, easy to hard':''} · Show your working in the space.</p>
 ${printView.pictures&&v?`<section class="pd-pictures">${v.frames.map((f,n)=>`<figure><img src="./${esc(f.image)}" alt=""><figcaption><b>${n+1}.</b> ${esc(f.caption)}</figcaption></figure>`).join('')}</section>`:''}
 <div class="pd-grid">${items.map((i,n)=>`${printView.deep&&n%DEEP_PER_TIER===0?`<h2 class="pd-tier">Part ${n/DEEP_PER_TIER+1} · ${DEEP_TIERS[n/DEEP_PER_TIER].label}<small>${DEEP_TIERS[n/DEEP_PER_TIER].note}</small></h2>`:''}${printQuestion(i,n)}`).join('')}</div>
 ${printView.answers?`<section class="pd-answers"><h2>Answers <small>for the grown-up · 家长答案页</small></h2><p class="pd-sub">${esc(l.title_en)}${l.title_zh?` · ${esc(l.title_zh)}`:''}</p><ol>${items.map(i=>`<li><strong>${esc(answerLabel(i,i.answer.display))}</strong>${i.solution_en?.length?`<span>${esc(i.solution_en[0])}</span>`:''}</li>`).join('')}</ol></section>`:''}</div>`;}
// Parent switch for the gentle practice timer, and how long recent sets took.
function timerPanel(){const st=loadSettings(),log=loadTimingLog().filter(r=>r.childId===state.activeChildId).slice(-8).reverse(),name=c=>state.children.find(x=>x.id===c)?.name||c,mins=s=>s<60?`${s} 秒`:`${Math.floor(s/60)} 分 ${s%60} 秒`;
 return `<section class="panel timer-panel"><div class="section-heading"><h2>练习计时</h2><span class="small muted">默认关闭</span></div><p>打开后，练习按每 5 题一轮计时：A 每轮 ${PER_QUESTION.A*5/60} 分钟，B 每轮 ${PER_QUESTION.B*5/60} 分钟。孩子开始做某一轮的题时，这一轮才开始计时；页面没打开时不计时。时间过半和时间到时，小蕨芽 Ferny 会在右下角出来提醒一下，几秒后自己离开。不锁题、不扣分、不算错。</p><div class="home-actions">${['A','B'].map(c=>`<button class="${st.timer[c]?'primary':'secondary'}" data-timer-toggle="${c}" aria-pressed="${st.timer[c]}">${esc(name(c))}：计时${st.timer[c]?'已打开':'已关闭'}</button>`).join('')}</div>
 <h3>${esc(name(state.activeChildId))} 最近的练习用时</h3>${log.length?`<div class="table-wrap"><table><thead><tr><th>日期</th><th>练习</th><th>题数</th><th>用时</th><th>每轮</th></tr></thead><tbody>${log.map(r=>`<tr><td>${esc(String(r.at).slice(0,10))}</td><td>${esc(allLessons().find(l=>l.id===r.lessonId)?.title_zh||r.lessonId)}${r.kind==='mistakes'?' · 错题':''}</td><td>${r.questions}</td><td>${mins(r.seconds)}</td><td class="small">${r.rounds.map(x=>mins(x)).join(' / ')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">做完一组练习后，这里会显示用了多长时间（不论计时是否打开都会记录）。</p>'}</section>`;}
function parentPage(){const ls=lessons().filter(l=>!l.library||attempts(l.id).length);return `<p class="eyebrow">给家长的观察窗口</p><h1 class="page-title">看见每一步理解。</h1><p class="muted">${state.activeChildId==='A'?'A：8 岁，在读 Year 4，持续强化 Year 4，同时学习 Year 5。':'B：6 岁，在读 Year 2，按 Year 3 安排学习。'}两个孩子的记录分别保存。</p>${parentMistakes()}${stickerPanel()}${timerPanel()}${notesFinder()}${curriculumParentOverview()}<div class="notice">记录只保存在当前设备的当前浏览器。清除网站数据会删除记录；换设备或浏览器时，请先导出备份。</div><section class="panel"><div class="section-heading"><h2>当前学习证据</h2><span class="small muted">完成题目 ≠ 稳定掌握</span></div>${ls.map(l=>{const m=mastered(l);return `<div class="evidence-row"><div><strong>${esc(l.title_zh)}</strong><p class="small muted">Year ${l.scope_id.slice(1)} · ${l.mode==='reinforce'?'持续强化':'新知识'}</p></div><span class="badge ${m.status==='retained'?'green':'blue'}">${esc(zhNames[m.status])}</span><span class="small">独立 ${m.independentCount||0} · 隔日 ${m.reviewCount||0}${getLessonProgress(state,state.activeChildId,l,content).needsNewReviewItems?'<br>现有复习题已用完，需新题继续观察':''}</span></div>`;}).join('')}<p class="small muted">独立表现只计入新题的首次无提示正确作答，并包含变式。看过提示、解法或重做的题，不会被累计成新的掌握证据。速度不作为学习下一课的门槛。</p></section><div class="parent-grid"><section class="panel"><h2>孩子档案</h2><form id="profile-form"><label class="field" for="learner-name">当前孩子的显示名<input id="learner-name" maxlength="24" value="${esc(child().name||'Learner '+state.activeChildId)}" required></label><button class="secondary" type="submit">保存名字</button></form><p class="small muted">可以只用昵称，不需要填写真实姓名或生日。</p></section><section class="panel"><h2>学习记录备份</h2><p>备份包含两个孩子的答题、提示使用与复习记录。</p><div class="home-actions"><button class="primary" data-action="export">导出备份</button><label class="secondary file-label">选择备份文件<input type="file" id="import-file" accept=".json,application/json"></label></div>${pendingImport?`<div class="notice"><p>文件有效，包含 ${pendingImport.attempts.length} 条答题记录。导入将替换当前两个孩子的记录。</p><button class="secondary" data-action="confirm-import">替换并导入</button> <button class="ghost" data-action="cancel-import">取消</button></div>`:''}</section></div><section class="panel"><h2>最近的作答</h2>${state.attempts.some(a=>a.childId===state.activeChildId)?`<div class="table-wrap"><table><thead><tr><th>日期 / 目标</th><th>答案</th><th>结果</th><th>独立程度</th></tr></thead><tbody>${state.attempts.filter(a=>a.childId===state.activeChildId).slice(-20).reverse().map(a=>`<tr><td>${esc(a.day)}<br><span class="small">${esc(allLessons().find(l=>l.id===a.lessonId)?.title_zh)}</span></td><td>${esc(answerLabel(allLessons().find(l=>l.id===a.lessonId)?.items.find(i=>i.id===a.itemId),a.response))}</td><td>${a.correct?'正确':'继续尝试'}</td><td>${a.viewedSolution?'已看解法':a.usedHint?'已用提示':!a.firstAttempt?'重复练习':a.eligible?'首次独立正确':a.stage==='guided'?'带练':a.stage==='practice'?'日常练习':'首次作答'}${a.stage==='review'?' · 隔日复习':''}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">开始答题后，这里会显示当前孩子最近的 20 次作答。</p>'}</section><section class="panel"><h2>本轮内容与教学使用</h2><p>Year 3–8 各年级课程均可从首页进入。每课先看 3 幅教学图（部分课有动画），然后做 20 题练习，全部做完再一起判分。第一次练习的最后 2～3 题是这一课的独立检查题，第一次就独立答对才计入掌握；之后的另一天，“Revisit” 里会有 2 题复习。需要测量、作图、调查和实验的内容附有生活小活动（见上面的每课讲解提示）。原有 8 节分数课及学习记录继续保留。普通练习题不计入独立掌握证据。</p><p>大孩子的 Year 4 强化始终保留；可以直接学习 Year 5，不需要先完成所有 Year 4 课程。</p><p class="small muted">这些状态是首轮教学观察规则，尚未经孩子试用验证。单次错误不会被认定为固定错因。</p></section>`;}
function enter(index){session.index=index;session.answer='';session.feedback=null;const i=session.items[index];session.hints=exposed(session.lesson.id,i.id,'hint')?getHints(i).length:0;session.showSolution=exposed(session.lesson.id,i.id,'solution');if(!exposure(i,'seen')){render();return;}if(i.stage==='worked'&&session.lesson.mode!=='reinforce'&&!exposure(i,'solution')){session.index=-1;render();return;}render();document.querySelector('#main')?.scrollIntoView({block:'start'});}
function advance(){if(session.index===session.items.length-1){session.finished=true;render();}else enter(session.index+1);}
function bind(){mountMotion();document.querySelectorAll('[data-print]').forEach(b=>b.onclick=()=>openPrint(b.dataset.print));
 document.querySelectorAll('[data-sticker-goal]').forEach(b=>b.onclick=()=>{const st=loadStickers();st.children[state.activeChildId].goal=Number(b.dataset.stickerGoal);if(!saveStickers(st))notice='无法保存贴纸设置。';render();});
 document.querySelectorAll('[data-sticker-give]').forEach(b=>b.onclick=()=>{const st=loadStickers(),kind=b.dataset.stickerGive;if(award(st,state.activeChildId,{key:`${kind}:${Date.now()}`,kind,note:kind==='paper'?'纸上练习':'家长的鼓励'}))saveStickers(st);render();});
 document.querySelectorAll('[data-sticker-redeem]').forEach(b=>b.onclick=()=>{const st=loadStickers();if(redeemStickers(st,state.activeChildId))saveStickers(st);render();});document.querySelectorAll('[data-print-opt]').forEach(c=>c.onchange=()=>{printView[c.dataset.printOpt]=c.checked;render();});document.querySelectorAll('[data-timer-toggle]').forEach(b=>b.onclick=()=>{const st=loadSettings();st.timer[b.dataset.timerToggle]=!st.timer[b.dataset.timerToggle];if(!saveSettings(st))notice='无法保存设置。';render();});document.querySelectorAll('[data-notes]').forEach(b=>b.onclick=()=>openNotes(b.dataset.notes));document.querySelectorAll('[data-notes-year]').forEach(b=>b.onclick=()=>{notesYear=Number(b.dataset.notesYear);render();});document.querySelectorAll('[data-print-year]').forEach(b=>b.onclick=()=>{printYear=Number(b.dataset.printYear);render();});
 bindLibrary();
 bindPictureFlow();
 bindSheet();
 document.querySelectorAll('[data-resume-lesson]').forEach(b=>b.onclick=()=>resumeSheet(b.dataset.resumeLesson));
 document.querySelectorAll('[data-knowledge]').forEach(b=>b.onclick=()=>openKnowledge(b.dataset.knowledge,b.dataset.fromLine||null));
 document.querySelectorAll('[data-line]').forEach(b=>b.onclick=()=>openLine(b.dataset.line));
 document.querySelectorAll('[data-checks]').forEach(b=>b.onclick=()=>{startLesson(b.dataset.checks);action('independent');});
 document.querySelectorAll('[data-child]').forEach(b=>b.onclick=()=>{const id=b.dataset.child;if(id!==state.activeChildId&&(session||!['home','parent','notes'].includes(view))){pendingChild=id;render();document.querySelector('[data-action="confirm-child"]')?.focus();return;}switchChild(id);});document.querySelector('[data-action="confirm-child"]')?.addEventListener('click',()=>{const id=pendingChild;pendingChild=null;switchChild(id);});document.querySelector('[data-action="cancel-child"]')?.addEventListener('click',()=>{pendingChild=null;render();});
 document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>startLesson(b.dataset.start));document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>startLesson(b.dataset.review,true));
 document.querySelectorAll('[data-compare]').forEach(b=>b.onclick=()=>{session.answer=b.dataset.compare;session.feedback=null;render();});
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));
 const form=document.querySelector('#answer-form');if(form)form.onsubmit=e=>{e.preventDefault();session.answer=document.querySelector('#answer').value;if(writeBlocked){render();return;}const result=recordAttempt(state,{childId:state.activeChildId,lessonId:session.lesson.id,itemId:session.items[session.index].id,response:session.answer},content);if(persist(result.state))session.feedback={...result.result,supported:!!(result.attempt?.usedHint||result.attempt?.viewedSolution)};render();};
 const input=document.querySelector('#answer');if(input)input.oninput=()=>{session.answer=input.value;};
 const profile=document.querySelector('#profile-form');if(profile)profile.onsubmit=e=>{e.preventDefault();const name=document.querySelector('#learner-name').value.trim();if(!name)return;if(persist({...state,children:state.children.map(c=>c.id===state.activeChildId?{...c,name}:c)}))notice='名字已保存。';render();};
 const file=document.querySelector('#import-file');if(file)file.onchange=async()=>{try{const f=file.files[0];if(!f)return;if(f.size>25_000_000)throw Error('文件过大。');const result=importBackup(await f.text(),content);if(result?.valid===false||result?.ok===false)throw Error(result.errors?.join('；')||result.error||'备份无效');pendingImport=result.state||result;notice='';}catch(e){notice='无法读取备份：'+e.message;pendingImport=null;}render();};
}
function action(a){
 if(a.startsWith('picture-')){pictureAction(a);return;}
 if(a==='start-sheet'){startSheet();return;}if(a==='resume-sheet'){resumeSheet();return;}if(a==='check-sheet'){checkSheet(sheet.itemIds);return;}if(a==='finish-anyway'){checkSheet(sheet.itemIds,{confirmedBlank:true});return;}if(a==='finish-back'){const first=pendingFinish?.first;pendingFinish=null;render();const q=document.getElementById(`question-${first}`);q?.scrollIntoView({block:'center'});q?.querySelector('input:not([type=hidden])')?.focus({preventScroll:true});return;}if(a==='new-sheet'){knowledgeId=sheet.lessonId;startSheet();return;}
 if(a==='reload'){location.reload();return;}
 if(a==='export-raw'){let raw;try{raw=localStorage.getItem(STORAGE_KEY);}catch{}const url=URL.createObjectURL(new Blob([raw||JSON.stringify(state)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='fern-maths-recovery.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 if(a==='intro'){showIntro();return;}
  if(a==='do-print'){rememberPrinted();window.print();return;}
  if(a==='print-new'){openPrint(printView.lessonId,true);return;}
  if(a==='print-pick'){view='print-pick';session=null;notice='';render();window.scrollTo(0,0);return;}
  if(['home','parent','review','stickers','lines'].includes(a)){view=a;session=null;notice='';pendingImport=null;render();window.scrollTo(0,0);return;}
 if(a==='begin')enter(0);
 if(a==='independent')enter(session.items.findIndex(i=>i.stage==='independent'));
 if(a==='next')advance();
 if(a==='hint'){const i=session.items[session.index];if(exposure(i,'hint'))session.hints++;render();}
 if(a==='solution'){if(exposure(session.items[session.index],'solution'))session.showSolution=true;render();}
 if(a==='export'){const data=exportBackup(state,content);const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`fern-maths-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice='备份已生成，请保留下载的 JSON 文件。';render();}
 if(a==='confirm-import'){persist(pendingImport,{replace:true});sheetData.sheets={};sheetData.sets={A:{},B:{}};saveSheets({replace:true});sheet=null;pendingImport=null;notice='备份已导入，两个孩子的记录已恢复。';render();}
 if(a==='cancel-import'){pendingImport=null;render();}
}
const SHEET_KEY='fern-maths.practice-sheets.v1';
let savedSheetsRaw=null;
let sheetData={version:1,sheets:{},sets:{A:{},B:{}},counts:{A:15,B:10}},sheet=null,sheetError='';
function savedSheet(lessonId){return sheetData.sets[state.activeChildId]?.[lessonId];}
function loadSheets(){try{savedSheetsRaw=localStorage.getItem(SHEET_KEY);const stored=JSON.parse(savedSheetsRaw||'null');if(!stored||stored.version!==1)return;for(const id of ['A','B']){if([10,15,20].includes(stored.counts?.[id]))sheetData.counts[id]=stored.counts[id];const candidates={...(stored.sets?.[id]||{})};if(stored.sheets?.[id]?.lessonId)candidates[stored.sheets[id].lessonId+(stored.sheets[id].kind==='mistakes'?'#mistakes':'')]=stored.sheets[id];for(const l of getLessonsForChild(content,id))for(const key of [l.id,l.id+'#mistakes']){const s=candidates[key],mistakes=key.endsWith('#mistakes');if(!s||(mistakes?!(s.itemIds?.length>=1&&s.itemIds.length<=20):![10,15,20,30].includes(s.itemIds?.length))||new Set(s.itemIds).size!==s.itemIds.length||!s.itemIds.every(i=>l.items.some(x=>x.id===i&&(mistakes?x.stage!=='worked':['practice','independent'].includes(x.stage)))))continue;const clean={lessonId:l.id,itemIds:s.itemIds,drafts:{},submitted:{},hints:{},...(mistakes?{kind:'mistakes'}:{}),...(s.finished===true?{finished:true}:{}),...(s.deep===true&&!mistakes&&s.itemIds.length===DEEP_SET_SIZE?{deep:true}:{})};for(const itemId of s.itemIds){if(typeof s.drafts?.[itemId]==='string'&&s.drafts[itemId].length<=160)clean.drafts[itemId]=s.drafts[itemId];const a=state.attempts.find(a=>a.id===s.submitted?.[itemId]&&a.childId===id&&a.itemId===itemId);if(a)clean.submitted[itemId]=a.id;if(Number.isInteger(s.hints?.[itemId]))clean.hints[itemId]=Math.max(0,Math.min(2,s.hints[itemId]));}sheetData.sets[id][key]=clean;if(stored.sheets?.[id]?.lessonId===l.id&&(stored.sheets[id].kind==='mistakes')===mistakes)sheetData.sheets[id]=clean;}}}catch{sheetError='Your previous practice sheet could not be reopened. Your recorded answers are still in 家长中心.';}}
function saveSheets({replace=false}={}){if(writeBlocked&&!replace)return false;try{if(!replace&&localStorage.getItem(SHEET_KEY)!==savedSheetsRaw){writeBlocked=true;storageError='Practice changed in another tab. Reload this page before continuing.';return false;}localStorage.setItem(SHEET_KEY,JSON.stringify(sheetData));savedSheetsRaw=localStorage.getItem(SHEET_KEY);sheetError='';return true;}catch{sheetError='Draft answers could not be saved. Keep this page open until you have checked your answers.';const el=document.getElementById('sheet-draft-notice');if(el)el.textContent=sheetError;return true;}}
// A lesson with a deep bank gets 30 questions in three parts (Warm up, Mix it up, Challenge); the others 20.
function setSize(l){return deepLesson(l)?DEEP_SET_SIZE:20;}
function startSheet(){if(writeBlocked){render();return;}const l=lessons().find(l=>l.id===knowledgeId);if(!l)return;const deep=deepLesson(l),count=setSize(l);const prior=[...state.exposures.filter(e=>e.childId===state.activeChildId&&e.kind==='seen').map(e=>e.itemId),...state.attempts.filter(a=>a.childId===state.activeChildId).map(a=>a.itemId)];/* The lesson's own-work check questions (2–3) go at the end of the set until the child has answered them once:
they are the only questions that count towards "mastered", and the set gives no hints or answers until it is finished. */const own=checks(l).filter(i=>!state.attempts.some(a=>a.childId===state.activeChildId&&a.itemId===i.id));let selection;if(deep)selection=selectDeepSet(l,prior,{own});else{selection=selectPracticeItems(l,count,prior);selection.items=[...selection.items.slice(0,count-own.length),...own];selection.repeatedCount=Math.max(0,selection.repeatedCount-own.length);}sheet={lessonId:l.id,itemIds:selection.items.map(i=>i.id),drafts:{},submitted:{},hints:{},...(deep?{deep:true}:{})};let next=state;for(const item of selection.items)next=recordExposure(next,{childId:state.activeChildId,lessonId:l.id,itemId:item.id,kind:'seen'},content);if(!persist(next)){render();return;}sheetData.sheets[state.activeChildId]=sheet;sheetData.sets[state.activeChildId][l.id]=sheet;if(!saveSheets()){render();return;}view='practice';notice=selection.repeatedCount?`${selection.repeatedCount} questions are familiar practice. Repeating them does not count as new independent evidence.`:'';render();window.scrollTo(0,0);/* On a wide iPad or Mac screen the title block can push question 1 below the fold: bring it into view. */const first=document.querySelector('.practice-question');if(first&&first.getBoundingClientRect().top>innerHeight*0.55)first.scrollIntoView({block:'start'});}
// Wrong answers are already in the learning record. A question stays "to try again" until the child's latest answer to it is right.
function mistakeList(childId=state.activeChildId,lessonId=null){const latest=new Map(),wrong=new Map();for(const a of state.attempts){if(a.childId!==childId||(lessonId&&a.lessonId!==lessonId)||a.stage==='worked')continue;const k=a.itemId;if(!latest.has(k)||latest.get(k).seq<a.seq)latest.set(k,a);if(!a.correct)wrong.set(k,(wrong.get(k)||0)+1);}
 const out=[];for(const[itemId,count]of wrong){const last=latest.get(itemId),lesson=allLessons().find(l=>l.id===last.lessonId),item=lesson?.items.find(i=>i.id===itemId);if(!item)continue;out.push({itemId,lesson,item,last,wrongCount:count,fixed:last.correct});}
 return out.sort((a,b)=>b.last.seq-a.last.seq);}
function startMistakes(lessonId,limit=20){if(writeBlocked){render();return;}const l=lessons().find(l=>l.id===lessonId);const items=mistakeList(state.activeChildId,lessonId).filter(m=>!m.fixed).slice(0,limit).map(m=>m.itemId);if(!l||!items.length)return;knowledgeId=l.id;
 sheet={kind:'mistakes',lessonId:l.id,itemIds:items,drafts:{},submitted:{},hints:{}};sheetData.sheets[state.activeChildId]=sheet;sheetData.sets[state.activeChildId][l.id+'#mistakes']=sheet;if(!saveSheets()){render();return;}view='practice';notice='';render();window.scrollTo(0,0);}
function resumeSheet(lessonId){sheet=lessonId?savedSheet(lessonId):sheetData.sheets[state.activeChildId];if(!sheet)return;sheetData.sheets[state.activeChildId]=sheet;saveSheets();view='practice';notice='';render();window.scrollTo(0,0);}
function sheetLesson(){return lessons().find(l=>l.id===sheet.lessonId);}
function sheetItem(id){return sheetLesson().items.find(i=>i.id===id);}
function sheetAttempt(id){return state.attempts.find(a=>a.id===sheet.submitted[id]&&a.childId===state.activeChildId&&a.itemId===id&&a.response===sheet.drafts[id]);}
function sheetQuestion(i,index){const raw=sheet.drafts[i.id]||'',done=sheet.finished,a=done?sheetAttempt(i.id):null,blank=!raw.trim();const input=i.choices?selectForItem(i,'sheet-answer-'+i.id,`data-sheet-input="${i.id}"`,raw):i.answer_spec.op==='compare_fractions'?signButtons('sheet-answer-'+i.id,`data-sheet-input="${i.id}"`,raw):`<input id="sheet-answer-${i.id}" data-sheet-input="${i.id}" class="answer-input" type="text" inputmode="${inputMode(i)}" autocomplete="off" spellcheck="false" maxlength="80" placeholder="${answerPlaceholder(i,'Number')}" value="${esc(raw)}" ${done?'readonly':''}>`;
 const result=!done?'':blank?`<div class="feedback incorrect"><strong>Not answered.</strong><p>Correct answer: ${esc(answerLabel(i,i.answer.display))}</p></div>`:a?.correct?`<div class="feedback correct"><strong>Correct.</strong></div>`:`<div class="feedback incorrect"><strong>Not quite.</strong><p>${esc(explainMistake(i,raw))}</p><p>Correct answer: ${esc(answerLabel(i,i.answer.display))}</p></div>`;
 const how=done&&!a?.correct?`<details class="sheet-solution" data-sheet-solution="${i.id}"><summary>Show me how</summary><div class="solution"><ol>${i.solution_en.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></div></details>`:'';
 const mark=!done?'':blank?'<span class="badge">Not answered</span>':a?.correct?'<span class="badge green">✓</span>':'<span class="badge red">✗</span>';
 return `<article class="practice-question ${done?(a?.correct?'answered result-correct':'result-wrong'):''}" id="question-${i.id}" data-question="${i.id}"><div class="question-heading"><span class="question-number">${index+1}</span><h2>${esc(i.prompt_en)}</h2>${mark}</div>${(i.diagram_note_en||i.representation?.diagram_note_en)?`<p class="small muted">${esc(i.diagram_note_en||i.representation.diagram_note_en)}</p>`:''}${questionPicture(i)}<form class="practice-answer ${done?'locked':''}" data-sheet-form="${i.id}"><label for="sheet-answer-${i.id}">Answer to question ${index+1}</label><div class="answer-row">${input}</div></form><div class="sheet-feedback" aria-live="polite">${result}</div>${how}</article>`;}

// After "Finish and check" the set gets its own results page: the score, the questions to look at again
// (with the correct answer and "Show me how"), what to do next, and ideas that connect to this one.
function resultsPage(){const l=sheetLesson(),rows=sheet.itemIds.map(sheetItem),n=rows.length,ok=i=>sheetAttempt(i.id)?.correct,correct=rows.filter(ok).length,wrong=rows.map((i,k)=>[i,k]).filter(([i])=>!ok(i)),open=mistakeList(state.activeChildId,l.id).filter(m=>!m.fixed).length,card=cards.find(c=>c.lessonId===l.id);
 const message=correct===n?'Every answer is right. Well done!':correct>=Math.ceil(n*0.75)?'Great work. Look at the ones below to see what to fix.':'Good effort. Look at the ones below together, then try again.';
 return `<div class="lesson-header"><button class="ghost" data-knowledge="${l.id}">Back to the pictures</button><span class="badge blue">Year ${l.scope_id.slice(1)} · Results</span></div>${learningSteps(1)}<section class="results-hero panel sheet-score" aria-live="polite"><p class="eyebrow">${sheet.kind==='mistakes'?'TRY AGAIN · RESULTS':'YOUR RESULTS'}</p><h1>${esc(l.title_en)}</h1><p class="results-score"><strong id="sheet-progress">${correct} / ${n} correct</strong></p>${tierScores(rows,ok)}<p>${message}</p>${stickerToast()}<div class="result-grid" aria-label="Every question">${rows.map((i,k)=>ok(i)?`<span class="done" aria-label="Question ${k+1}: right">${k+1}</span>`:`<a class="wrong" href="#question-${i.id}" aria-label="Question ${k+1}: look again">${k+1}</a>`).join('')}</div><div class="home-actions">${open?`<button class="primary" data-mistakes="${l.id}">Practise the wrong ones · ${open}</button>`:''}<button class="${open?'secondary':'primary'}" data-action="new-sheet">Do another set of ${n}</button><button class="ghost" data-knowledge="${l.id}">Back to the pictures</button></div>${sheet.kind!=='mistakes'&&lineNextButtons(l)?`<p class="line-next-row">Ready for more? ${lineNextButtons(l)}</p>`:''}</section>${wrong.length?`<section class="results-review"><h2>Look at these again</h2><p class="muted">The right answer is under each one. Open “Show me how” to see the steps.</p><div class="practice-list">${wrong.map(([i,k])=>sheetQuestion(i,k)).join('')}</div></section>`:''}${card?.connects_to?.length?`<section class="results-next panel">${relatedLinks(card.connects_to,'Ideas to explore next')}</section>`:''}`;}
// A 30-question set is three parts of ten: a banner opens each part. tierOf(n) is the part a question belongs to.
function tierOf(n){return sheet?.deep?DEEP_TIERS[Math.min(DEEP_TIERS.length-1,Math.floor(n/DEEP_PER_TIER))]:null;}
function tierBanner(n){const t=tierOf(n);if(!t||n%DEEP_PER_TIER!==0)return '';const k=n/DEEP_PER_TIER;return `<div class="practice-tier tier-${t.depth}" id="part-${k+1}"><p class="eyebrow">PART ${k+1} OF ${DEEP_TIERS.length} · QUESTIONS ${n+1}–${n+DEEP_PER_TIER}</p><h2>${t.label}</h2><p>${t.note}</p></div>`;}
function tierScores(rows,ok){if(!sheet?.deep)return '';return `<p class="tier-scores" aria-label="Score by part">${DEEP_TIERS.map((t,k)=>{const part=rows.slice(k*DEEP_PER_TIER,(k+1)*DEEP_PER_TIER);return `<span class="tier-${t.depth}">${t.label} <b>${part.filter(ok).length}/${part.length}</b></span>`;}).join('')}</p>`;}
function practicePage(){if(sheet.finished)return resultsPage();const l=sheetLesson(),rows=sheet.itemIds.map(sheetItem),filled=rows.filter(i=>(sheet.drafts[i.id]||'').trim()).length,correctCount=sheet.finished?sheet.itemIds.filter(id=>sheetAttempt(id)?.correct).length:0;
 const finishButton=`<button class="primary" data-action="check-sheet">Finish and check</button>`;
 return `<div class="lesson-header"><button class="ghost" data-knowledge="${l.id}">Back to the pictures</button><span class="badge blue">Year ${l.scope_id.slice(1)} · Practice set</span></div>${learningSteps(1)}<div class="sheet-heading"><p class="eyebrow">${sheet.kind==='mistakes'?'TRY AGAIN':'ONE IDEA. ROOM TO PRACTISE.'}</p><h1>${esc(l.title_en)}</h1><p>${sheet.finished?`You finished this set.`:sheet.kind==='mistakes'?`${rows.length} question${rows.length===1?'':'s'} you found tricky before. Take your time, then press <strong>Finish and check</strong>.`:`${rows.length} questions. Answer them all, then press <strong>Finish and check</strong> to see how you did.`}</p></div><div class="sheet-toolbar"><strong id="sheet-progress">${sheet.finished?`${correctCount} / ${rows.length} correct`:`${filled} / ${rows.length} answered`}</strong><span class="round-timer" data-round-timer hidden><span data-round-label>Round 1</span><span class="rt-bar" aria-hidden="true"><span data-rt-fill style="width:100%"></span></span></span>${sheet.finished?'':finishButton}</div>${sheet.finished?`<section class="sheet-score panel" aria-live="polite"><h2>${correctCount} of ${rows.length} correct</h2><p>${correctCount===rows.length?'Every answer is right. Well done!':'Look at the questions marked ✗. Open “Show me how” to see the steps.'}</p></section>`:''}<p id="sheet-draft-notice" role="alert" class="${sheetError?'notice':''}">${esc(sheetError)}</p><details class="question-index"><summary>Jump to a question</summary><nav class="question-jumps" aria-label="Jump to a question">${rows.map((i,n)=>`<a href="#question-${i.id}" class="${sheet.finished?(sheetAttempt(i.id)?.correct?'done':'wrong'):(sheet.drafts[i.id]||'').trim()?'filled':''}" aria-label="Question ${n+1}">${n+1}</a>`).join('')}</nav></details><div class="practice-list">${rows.map((i,n)=>`${tierBanner(n)}${n%5===0&&!(sheet.deep&&n%DEEP_PER_TIER===0)?`<div class="practice-round"><h2>Round ${Math.floor(n/5)+1} · Questions ${n+1}–${Math.min(n+5,rows.length)}</h2><p>${n===0?'Try a few at a time.':'A good place to pause. Come back when you are ready.'}</p></div>`:''}${sheetQuestion(i,n)}`).join('')}</div><section class="sheet-end panel">${sheet.finished?`<h2>${correctCount} of ${rows.length} correct</h2>${sheet.kind==='mistakes'?(mistakeList(state.activeChildId,l.id).some(m=>!m.fixed)?`<button class="primary" data-mistakes="${l.id}">Try the tricky ones again</button>`:'<p>No tricky questions left in this topic.</p>'):`<button class="primary" data-action="new-sheet">Start a new set of ${rows.length}</button>`}`:`<h2>All done?</h2><p>When every question has an answer, press Finish and check. Your answers are saved if you stop and come back later.</p>${finishButton}`}<button class="ghost" data-knowledge="${l.id}">Back to the pictures</button></section>${pendingFinish?finishPrompt():''}`;}

function updateQuestion(id){if(storageError){render();return;}const el=document.getElementById(`question-${id}`);if(el)el.outerHTML=sheetQuestion(sheetItem(id),sheet.itemIds.indexOf(id));const count=sheet.itemIds.filter(id=>sheetAttempt(id)).length,correct=sheet.itemIds.filter(id=>sheetAttempt(id)?.correct).length;const progress=document.getElementById('sheet-progress');if(progress)progress.textContent=`${count} / ${sheet.itemIds.length} checked · ${correct} correct`;updateSheetProgress();bindSheet();}
function updateSheetProgress(){if(!sheet||sheet.finished)return;const filled=sheet.itemIds.filter(id=>(sheet.drafts[id]||'').trim()).length;const progress=document.getElementById('sheet-progress');if(progress)progress.textContent=`${filled} / ${sheet.itemIds.length} answered`;document.querySelectorAll('.question-jumps a').forEach(a=>a.classList.toggle('filled',!!(sheet.drafts[a.hash.replace('#question-','')]||'').trim()));}

function keepKeyboardFlow(id){if(lastInput!=='keyboard')return;const order=sheet.itemIds,done=x=>sheetAttempt(x)?.correct;const target=done(id)?order.slice(order.indexOf(id)+1).concat(order).find(x=>!done(x)):id;requestAnimationFrame(()=>{const input=target&&document.querySelector(`[data-sheet-input="${target}"]`);const target2=input?.type==='hidden'?(input.nextElementSibling?.querySelector('input:checked')||input.nextElementSibling?.querySelector('input')):input;if(target2){target2.focus();if(target2.type==='text')target2.select();}});}
// Practice sets are marked only when the child finishes the whole set: no checking, hints or solutions on the way.
let pendingFinish=null;
function finishPrompt(){return `<div class="switch-backdrop"><div class="switch-confirm" role="alertdialog" aria-modal="true" aria-labelledby="finish-title"><h2 id="finish-title">${pendingFinish.blank} question${pendingFinish.blank===1?' is':'s are'} still empty</h2><p>You can go back and answer ${pendingFinish.blank===1?'it':'them'}, or finish now. Empty questions count as not answered.</p><div class="home-actions"><button class="primary" data-action="finish-back">Go back and answer</button><button class="secondary" data-action="finish-anyway">Finish now</button></div></div></div>`;}
function checkSheet(ids,{confirmedBlank=false}={}){if(writeBlocked){render();return;}if(sheet.finished)return;
 const invalid=[];for(const id of ids){const raw=(sheet.drafts[id]||'').trim();if(!raw)continue;const r=gradeAnswer(sheet.drafts[id],sheetItem(id).answer);if(!r.valid)invalid.push([id,r.error]);}
 if(invalid.length){render();for(const[id,error]of invalid){const box=document.querySelector(`#question-${id} .sheet-feedback`);if(box)box.innerHTML=`<p class="notice" role="alert">${esc(error)}</p>`;}document.getElementById(`question-${invalid[0][0]}`)?.scrollIntoView({block:'center'});return;}
 const blank=ids.filter(id=>!(sheet.drafts[id]||'').trim());
 if(blank.length&&!confirmedBlank){pendingFinish={blank:blank.length,first:blank[0]};render();document.querySelector('[data-action="finish-back"]')?.focus();return;}
 pendingFinish=null;let next=state;const changes={};
 for(const id of ids){const raw=(sheet.drafts[id]||'').trim();if(!raw)continue;const old=sheetAttempt(id);if(old)continue;const result=recordAttempt(next,{childId:state.activeChildId,lessonId:sheet.lessonId,itemId:id,response:sheet.drafts[id]},content);if(!result.result.valid)continue;next=result.state;changes[id]=result.attempt.id;}
 if(!persist(next)){render();return;}Object.assign(sheet.submitted,changes);recordFinishedSet(sheet);sheet.finished=true;saveSheets();awardForSheet();render();window.scrollTo(0,0);}
// ---- Sticker book: a small reward kept apart from the learning record ----
let justEarned=null; // {sheet, list} for the results page that follows a check
function awardForSheet(){const st=loadStickers(),id=state.activeChildId,n=sheet.itemIds.length,answered=sheet.itemIds.filter(x=>String(sheet.drafts?.[x]??'').trim()).length,correct=sheet.itemIds.filter(x=>sheetAttempt(x)?.correct).length;
 const list=stickersForSheet(st,id,{lessonId:sheet.lessonId,kind:sheet.kind==='mistakes'?'mistakes':'practice',total:n,answered,correct});if(list.length)saveStickers(st);justEarned={sheet,list};}
function stickerToast(){if(!justEarned||justEarned.sheet!==sheet||!justEarned.list.length)return '';const list=justEarned.list;return `<div class="sticker-earned" role="status"><div class="sticker-row">${list.map((e,i)=>stickerArt(e,stickerIndex(e))).join('')}</div><p><strong>${list.length===1?'You earned a sticker!':`You earned ${list.length} stickers!`}</strong> ${list.map(e=>STICKER_KINDS[e.kind].title).join(' · ')}. <button class="ghost" data-action="stickers">Open your sticker book</button></p></div>`;}
function stickerIndex(e){return loadStickers().children[state.activeChildId].earned.findIndex(x=>x.key===e.key);}
function stickerCard(){const st=loadStickers(),s=stickerSummary(st,state.activeChildId),latest=st.children[state.activeChildId].earned.slice(-3);return `<section class="sticker-card" aria-label="Sticker book"><div class="sticker-mini">${latest.length?latest.map(e=>stickerArt(e,stickerIndex(e),48)).join(''):`<span class="sticker-ferny">${fernyArt()}</span>`}</div><div class="sticker-text"><strong>Sticker book · ${s.total}</strong><span>${s.ready?'This page is full! Show a grown-up.':s.total?`${s.toward} of ${s.goal} on this page`:'Finish a practice set to earn your first sticker.'}</span><span class="progress-bar small" aria-hidden="true"><span style="width:${Math.round(s.toward/s.goal*100)}%"></span></span></div><button class="secondary" data-action="stickers">Open</button></section>`;}
function stickersPage(){const st=loadStickers(),c=st.children[state.activeChildId],s=stickerSummary(st,state.activeChildId),title=id=>allLessons().find(l=>l.id===id)?.title_en||'';
 return `<div class="lesson-header"><button class="ghost" data-action="home">Back to my learning map</button></div><p class="eyebrow">MY STICKER BOOK</p><h1 class="page-title">${c.earned.length?`${c.earned.length} sticker${c.earned.length===1?'':'s'}`:'My sticker book'}</h1><div class="library-progress"><span>${s.ready?'This page is full! Show a grown-up.':`${s.toward} of ${s.goal} on this page${s.redeemed?` · ${s.redeemed} page${s.redeemed===1?'':'s'} finished before`:''}`}</span><span class="progress-bar" aria-hidden="true"><span style="width:${Math.round(s.toward/s.goal*100)}%"></span></span></div>${c.earned.length?`<div class="sticker-grid">${c.earned.map((e,i)=>`<div class="sticker"><div>${stickerArt(e,i,84)}</div><b>${esc(STICKER_KINDS[e.kind].title)}</b><small>${esc(e.lessonId?title(e.lessonId):e.note||'')}</small><small>${esc(e.date)}</small></div>`).reverse().join('')}</div>`:`<div class="sticker-empty">${fernyArt()}<p>Finish a practice set to earn your first sticker. Every answer right earns a second one.</p></div>`}<p class="small muted">How to earn: finish a practice set (1), get every answer right (+1), fix all the tricky ones in a topic (1 a day). Grown-ups can add stickers for paper practice.</p>`;}
function stickerPanel(){const st=loadStickers(),id=state.activeChildId,c=st.children[id],s=stickerSummary(st,id),name=state.children.find(x=>x.id===id)?.name||id;
 return `<section class="panel sticker-panel"><div class="section-heading"><h2>贴纸册</h2><span class="small muted">${esc(name)} · 共 ${s.total} 张 · 这一页 ${s.toward}/${s.goal}${s.redeemed?` · 已兑换 ${s.redeemed} 次`:''}</span></div><p class="small muted">规则：一课的练习第一次做完得 1 张，全对再加 1 张，把一课的错题全部改对每天可得 1 张。不比速度、不比孩子、不计连续天数。贴纸不算学习证据，和学习记录分开保存。</p><div class="home-actions"><span class="small">集满几张兑换一次：</span>${STICKER_GOALS.map(g=>`<button class="${g===c.goal?'primary':'secondary'}" data-sticker-goal="${g}" aria-pressed="${g===c.goal}">${g}</button>`).join('')}</div><div class="home-actions"><button class="secondary" data-sticker-give="paper">发一张：纸上练习</button><button class="secondary" data-sticker-give="parent">发一张：鼓励</button>${s.ready?'<button class="primary" data-sticker-redeem>这一页已兑换，翻到下一页</button>':''}</div>${c.earned.length?`<div class="sticker-row small-row">${c.earned.slice(-8).map(e=>stickerArt(e,stickerIndex(e),40)).join('')}</div>`:''}</section>`;}
function bindSheet(){if(view==='practice'&&sheet&&!sheet.finished)attachTimer(sheet,state.activeChildId,loadSettings().timer[state.activeChildId]);document.querySelectorAll('[data-sheet-input]').forEach(input=>input.oninput=()=>{if(writeBlocked){render();return;}sheet.drafts[input.dataset.sheetInput]=input.value;if(!saveSheets()){render();return;}const feedback=document.querySelector(`#question-${input.dataset.sheetInput} .sheet-feedback`);if(feedback)feedback.innerHTML='';const q=document.getElementById('question-'+input.dataset.sheetInput);q?.classList.remove('answered');q?.querySelector('.question-heading>.badge')?.remove();updateSheetProgress();});document.querySelectorAll('[data-sheet-form]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const order=sheet.itemIds,next=order[order.indexOf(form.dataset.sheetForm)+1];const el=next&&document.querySelector(`#question-${next} [data-sheet-input]:not([type=hidden]), #question-${next} [data-choice-for]`);if(el)el.focus();else document.querySelector('[data-action="check-sheet"]')?.focus();});document.querySelectorAll('[data-mistakes]').forEach(b=>b.onclick=()=>startMistakes(b.dataset.mistakes,Number(b.dataset.fixLimit)||20));document.querySelectorAll('[data-sheet-hint]').forEach(b=>b.onclick=()=>{const id=b.dataset.sheetHint;if(persist(recordExposure(state,{childId:state.activeChildId,lessonId:sheet.lessonId,itemId:id,kind:'hint'},content))){sheet.hints[id]=Math.min(getHints(sheetItem(id)).length,(sheet.hints[id]||0)+1);saveSheets();updateQuestion(id);}else render();});document.querySelectorAll('details[data-sheet-solution]').forEach(d=>d.addEventListener('toggle',()=>{if(d.open&&!exposed(sheet.lessonId,d.dataset.sheetSolution,'solution'))persist(recordExposure(state,{childId:state.activeChildId,lessonId:sheet.lessonId,itemId:d.dataset.sheetSolution,kind:'solution'},content));}));}
function getHints(i){const s=i.answer_spec;switch(s.op){case 'unit_of_whole':return [`The denominator ${s.denominator} means ${s.denominator} equal groups. Share ${s.whole} equally between them.`,`Find one group by calculating ${s.whole} ÷ ${s.denominator}. Then multiply your answer by ${s.denominator} to check the total.`];case 'whole_from_unit':return [`${s.part} is just one of ${s.denominator} equal parts.`,`The whole has ${s.denominator} parts, so calculate ${s.part} × ${s.denominator}.`];case 'nonunit_of_whole':return [`First share ${s.whole} into ${s.denominator} equal groups: ${s.whole} ÷ ${s.denominator}.`,`You need ${s.numerator} groups. Multiply the size of one group by ${s.numerator}.`];case 'whole_from_nonunit':return [`${s.part} is the amount in ${s.numerator} equal parts. Find one part using ${s.part} ÷ ${s.numerator}.`,`The whole has ${s.denominator} parts. Multiply the size of one part by ${s.denominator}.`];default:return i.hints_en;}}
function explainMistake(i,raw){const s=i.answer_spec,n=Number(raw);if(s.curriculum_id)return i.hints_en?.[0]||'Try a hint to see the next step.';switch(s.op){case 'unit_of_whole':return `${Number.isSafeInteger(n)&&Math.abs(n)<100000?`${n} in each of ${s.denominator} groups would make ${n*s.denominator}, but the total is ${s.whole}. `:''}The denominator means ${s.denominator} equal groups. Find one group: ${s.whole} ÷ ${s.denominator}.`;case 'whole_from_unit':return `${s.part} is one part, not the whole. There are ${s.denominator} equal parts, so multiply ${s.part} by ${s.denominator}.`;case 'nonunit_of_whole':return `Find one part first: ${s.whole} ÷ ${s.denominator}. Then take ${s.numerator} of those parts.`;case 'whole_from_nonunit':return `${s.part} is the amount in ${s.numerator} parts. Divide by ${s.numerator} to find one part, then multiply by ${s.denominator} for the whole.`;case 'fraction_at_tick':return `There are ${s.parts} equal spaces in the whole. Count ${s.tick} spaces from zero to the point. Write travelled spaces / total spaces.`;case 'compare_fractions':return `Both fractions use the same-sized parts. Compare how many parts there are, and choose <, = or >.`;case 'add_fractions':return `Both fractions use parts of size 1/${s.left[1]}. Add the top numbers; the size of the parts stays the same.`;case 'subtract_fractions':return `Both fractions count the same-sized parts. Subtract the top numbers; keep the denominator ${s.left[1]}.`;default:return i.hints_en?.[0]||'Try a hint to see the next step.';}}

let quiz=null;
function startQuiz(id){if(writeBlocked){render();return;}const l=lessons().find(l=>l.id===id);if(!l)return;let next=state;for(const i of checks(l))next=recordExposure(next,{childId:state.activeChildId,lessonId:l.id,itemId:i.id,kind:'seen'},content);if(!persist(next)){render();return;}quiz={lessonId:id,answers:{},errors:{},results:null};view='quiz';notice='';render();window.scrollTo(0,0);}
function quizNextStep(l){const p=getLessonProgress(state,state.activeChildId,l,content,today());if(p.reviewAvailable)return 'Your fresh review is ready in Revisit.';if(p.reviewDueDate)return 'Come back another day for a fresh review.';if(p.needsNewReviewItems)return 'You have finished this set of check questions. Explore another picture card, or keep practising.';return 'You have already revisited this idea. Explore another picture card, or keep practising.';}
function quizPage(){const l=lessons().find(l=>l.id===quiz.lessonId),items=checks(l),repeated=items.some(i=>attempts(l.id,i.id).length>0);if(quiz.results){const correct=quiz.results.filter(r=>r.correct).length;return `${learningSteps(3)}<section class="quiz-summary panel"><p class="eyebrow">YOUR SHORT CHECK</p><h1>${correct===items.length?'You worked through it.':'Keep building your idea.'}</h1><p>${correct} of ${items.length} answers fit. There is no rush.</p>${quiz.results.map((r,n)=>{const i=items[n];return `<article class="quiz-result"><h2>Question ${n+1}</h2><p>${esc(i.prompt_en)}</p><p>Your answer: <strong>${esc(answerLabel(i,r.response))}</strong> · ${r.correct?'Correct':'Let’s revisit this'}</p>${!r.correct?`<details data-quiz-solution="${i.id}"><summary>Show me how</summary><div class="solution"><ol>${i.solution_en.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><strong>${esc(answerLabel(i,i.answer.display))}</strong></div></details>`:''}</article>`;}).join('')}<p class="small muted">A few questions help us decide what to revisit. They do not tell the whole story.</p><div class="home-actions"><button class="primary" data-knowledge="${l.id}">See the teaching pictures</button><button class="secondary" data-action="home">Back to my learning</button></div><p>${esc(quizNextStep(l))}</p>${progressionPanel(l)}</section>`;}return `<div class="lesson-header"><button class="ghost" data-knowledge="${l.id}">Back to teaching</button><span class="badge blue">Short check · ${items.length} questions</span></div>${learningSteps(3)}<section class="quiz-intro"><h1>What can you do on your own?</h1><p>Try these without maths hints. We will look at your answers together at the end.</p>${repeated?'<p class="notice">Some questions are familiar. This time, use them for practice.</p>':''}<p class="small muted">No timer. If you are stuck, you can go back to the pictures.</p></section><form id="quiz-form"><div class="practice-list">${items.map((i,n)=>`<article class="practice-question" data-quiz-item="${i.id}"><div class="question-heading"><span class="question-number">${n+1}</span><h2>${esc(i.prompt_en)}</h2></div>${i.diagram_note_en?`<p class="small">${esc(i.diagram_note_en)}</p>`:''}${questionPicture(i)}<label for="quiz-${i.id}">Your answer</label>${i.choices?selectForItem(i,'quiz-'+i.id,`data-quiz-input="${i.id}"`,quiz.answers[i.id]||''):i.answer_spec.op==='compare_fractions'?signButtons('quiz-'+i.id,`data-quiz-input="${i.id}"`,quiz.answers[i.id]||''):`<input class="answer-input" id="quiz-${i.id}" data-quiz-input="${i.id}" type="text" inputmode="${inputMode(i)}" maxlength="80" autocomplete="off" value="${esc(quiz.answers[i.id]||'')}" placeholder="${answerPlaceholder(i,'Number')}">`}${quiz.errors[i.id]?`<p class="notice" role="alert">${esc(quiz.errors[i.id])}</p>`:''}</article>`).join('')}</div><div class="quiz-submit"><button class="primary" type="submit">Finish my check</button><p class="small muted">Unsubmitted answers stay on this screen only.</p></div></form>`;}
function submitQuiz(){if(writeBlocked){render();return;}const l=lessons().find(l=>l.id===quiz.lessonId),items=checks(l);quiz.errors={};for(const i of items){const result=gradeAnswer(quiz.answers[i.id]||'',i.answer);if(!result.valid)quiz.errors[i.id]=(quiz.answers[i.id]||'').trim()?result.error:'Add an answer when you are ready.';}if(Object.keys(quiz.errors).length){render();document.querySelector('[role="alert"]')?.scrollIntoView({block:'center'});return;}let next=state;const results=[];for(const i of items){const r=recordAttempt(next,{childId:state.activeChildId,lessonId:l.id,itemId:i.id,response:quiz.answers[i.id]},content);next=r.state;results.push(r.attempt);}if(persist(next)){quiz.results=results;render();window.scrollTo(0,0);}else render();}
function bindPictureFlow(){document.querySelectorAll('[data-picture-step]').forEach(b=>b.onclick=()=>{learnView.frame=Number(b.dataset.pictureStep);render();});document.querySelectorAll('[data-guided-choice]').forEach(b=>b.onclick=()=>{learnView.choice=b.dataset.guidedChoice;render();});document.querySelectorAll('[data-quiz]').forEach(b=>b.onclick=()=>startQuiz(b.dataset.quiz));document.querySelectorAll('[data-quiz-input]').forEach(input=>input.oninput=()=>{quiz.answers[input.dataset.quizInput]=input.value;});const form=document.getElementById('quiz-form');if(form)form.onsubmit=e=>{e.preventDefault();submitQuiz();};document.querySelectorAll('[data-quiz-solution]').forEach(el=>el.querySelector('summary').onclick=e=>{if(!el.open&&!persist(recordExposure(state,{childId:state.activeChildId,lessonId:quiz.lessonId,itemId:el.dataset.quizSolution,kind:'solution'},content))){e.preventDefault();render();}});}

let curriculum={years:[],coverage:[]},libraryYear=null,libraryDomain='All';
const curriculumLessons=year=>lessons().filter(l=>l.library&&(!year||Number(l.scope_id.slice(1))===Number(year)));
const currentLibraryYear=()=>libraryYear||startYear();
function yearPicker(selected=currentLibraryYear()){return `<div class="year-picker" role="group" aria-label="Choose a year">${[3,4,5,6,7,8].map(y=>`<button class="${Number(selected)===y?'primary':'secondary'}" data-year="${y}" aria-pressed="${Number(selected)===y}"><span>Year ${y}</span>${state.activeChildId==='B'&&y===3?'<small>Your starting point</small>':state.activeChildId==='A'&&y===4?'<small>Keep it strong</small>':state.activeChildId==='A'&&y===5?'<small>Your starting point</small>':''}</button>`).join('')}</div>`;}
function libraryPage(){const year=currentLibraryYear(),ls=curriculumLessons(year),topics=topicsForYear(year).filter(t=>t.lessonIds.some(id=>ls.some(l=>l.id===id))),loose=ls.filter(l=>!topicOf(l.id));if(loose.length)topics.push({id:`Y${year}-T99`,year,domain:loose[0].domain,title_en:'More ideas',title_zh:'其他',lessonIds:loose.map(l=>l.id)});
 const domains=[...new Set(topics.map(t=>t.domain))],shown=libraryDomain==='All'?topics:topics.filter(t=>t.domain===libraryDomain),done=ls.filter(practisedTopic).length,topicsDone=topics.filter(t=>t.lessonIds.every(id=>{const l=ls.find(x=>x.id===id);return l&&practisedTopic(l);})).length;
 return `<div class="lesson-header"><button class="ghost" data-action="home">Back to my learning map</button></div><h1 class="page-title">Year ${year} maths</h1>${yearPicker(year)}<div class="library-progress"><span>${topicsDone} of ${topics.length} topics done · ${done} of ${ls.length} steps practised</span><span class="progress-bar" aria-hidden="true"><span style="width:${ls.length?Math.round(done/ls.length*100):0}%"></span></span></div><div class="domain-picker" role="group" aria-label="Choose a maths topic">${['All',...domains].map(d=>`<button class="${d===libraryDomain?'primary':'secondary'}" data-domain="${esc(d)}" aria-pressed="${d===libraryDomain}">${esc(d)}</button>`).join('')}</div>${[...new Set(shown.map(t=>t.domain))].map(d=>`<section class="library-domain"><h2>${esc(d)}</h2><div class="topic-grid topic-cards">${shown.filter(t=>t.domain===d).map(t=>topicCard(t,ls)).join('')}</div></section>`).join('')}`;}
function activityPanel(l){const a=l.activity;if(!a)return '';return `<section class="activity-panel"><p class="eyebrow">TRY IT IN REAL LIFE</p><h3>${esc(a.title_en)}</h3>${a.materials_en?.length?`<p><strong>You will need:</strong> ${a.materials_en.map(esc).join(', ')}</p>`:''}<ol>${a.steps_en.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p class="small">Show or explain what you found to someone at home.</p><details><summary lang="zh-CN">给家长的观察提示</summary><p lang="zh-CN">${esc(a.observe_zh)}</p><p class="small" lang="zh-CN">页面答题不能替代这项实际操作；请另外观察孩子的操作和解释。</p></details></section>`;}
function progressionPanel(l){if(!l.library)return '';const ls=curriculumLessons(Number(l.scope_id.slice(1))),idx=ls.findIndex(x=>x.id===l.id),year=Number(l.scope_id.slice(1)),st=stepOf(l.id),inTopic=st&&st.index<st.count-1?ls.find(x=>x.id===st.topic.lessonIds[st.index+1]):null,next=inTopic||ls[idx+1];return `<section class="progression-panel"><h3>Where would you like to go next?</h3>${next?`<button class="secondary" data-knowledge="${next.id}">${inTopic?`Step ${st.index+2}: `:''}${esc(next.title_en)}</button>`:''}${lineNextButtons(l)}<button class="secondary" data-year="${year}">Choose another Year ${year} idea</button>${year<8?`<button class="ghost" data-year="${year+1}" data-open-domain="${esc(l.domain)}">More ${esc(l.domain)} in Year ${year+1}</button>`:''}</section>`;}
// Answers are chosen by tapping one large option, not from a dropdown. A hidden field keeps the id and data
// attribute the save and grading code already read; the radio buttons give arrow-key support on a Mac.
function choiceButtons(id,attribute,options,value='',name='Choose an answer'){return `<input type="hidden" id="${esc(id)}" ${attribute} value="${esc(value)}"><div class="choice-buttons ${options.every(o=>o.label.length<=3)?'compact':''}" role="radiogroup" aria-label="${esc(name)}">${options.map(o=>`<label class="choice-button"><input type="radio" name="${esc(id)}-choice" value="${esc(o.value)}" data-choice-for="${esc(id)}" ${String(o.value)===String(value)?'checked':''}${o.aria?` aria-label="${esc(o.aria)}"`:''}><span>${esc(o.label)}</span></label>`).join('')}</div>`;}
function selectForItem(i,id,attribute,value=''){return choiceButtons(id,attribute,i.choices.map((label,n)=>({value:String(n+1),label})),value);}
function signButtons(id,attribute,value=''){return choiceButtons(id,attribute,[['<','less than'],['=','equal to'],['>','greater than']].map(([v,a])=>({value:v,label:v,aria:a})),value,'Choose a sign');}
addEventListener('change',e=>{const r=e.target;if(!r.matches?.('[data-choice-for]'))return;const holder=document.getElementById(r.dataset.choiceFor);if(!holder)return;holder.value=r.value;holder.dispatchEvent(new Event('input',{bubbles:true}));});
function answerLabel(i,value){if(!i?.choices)return value;const n=Number(value);return Number.isInteger(n)&&n>=1&&n<=i.choices.length?i.choices[n-1]:value;}
function curriculumParentOverview(){if(!curriculum.years.length)return '';return `<section class="panel"><h2>Year 3–8 全课程</h2><p>按官方逐年级目标组织，包含图示教学、练习、独立检查、隔日复习和需要实际操作的活动。Year 1–2 不在本次范围内。课内短检查的状态只反映这些题的表现，不能据此认定整年或所有实际技能已掌握。</p><div class="coverage-grid">${curriculum.years.map(y=>`<div><strong>Year ${y.year}</strong><p>${y.lessons} 课 · ${y.objectives} 项课标目标映射</p><button class="secondary" data-year="${y.year}">查看课程</button><details><summary>年级教学建议</summary><p>${esc(y.age_guidance_zh)}</p></details></div>`).join('')}</div><p>知识线（Follow an idea）：${LINES.length} 条，每条从 Year 3 到 Year 8 每年一课，同一个知识接着往下学，比如学完 Year 3 的加法可以直接接 Year 4 的加法，不用先学完整个 Year 3；卡住了就退回上一课。只是建议顺序，不是解锁条件。 <button class="secondary" data-action="lines">查看知识线</button></p><p class="small muted">数学年级与阅读支持分别考虑：6 岁孩子仍可慢速朗读、看图、点选；更高年级逐渐增加多步推理。实际测量、作图和调查的活动需要家长观察，自动判分无法核实。</p></section>`;}
function bindLibrary(){document.querySelectorAll('[data-year]').forEach(b=>b.onclick=()=>{libraryYear=Number(b.dataset.year);libraryDomain=b.dataset.openDomain||'All';view='library';session=null;notice='';render();window.scrollTo(0,0);});document.querySelectorAll('[data-domain]').forEach(b=>b.onclick=()=>{libraryDomain=b.dataset.domain;render();});}

async function init(){try{const r=await fetch('./content.json');if(!r.ok)throw Error('Lesson content unavailable');content=augmentContent(await r.json());const kr=await fetch('./knowledge-cards.json');if(!kr.ok)throw Error('Knowledge cards unavailable');cards=await kr.json();const vr=await fetch('./visual-lessons.json');if(!vr.ok)throw Error('Teaching pictures unavailable');visuals=await vr.json();const cr=await fetch('./curriculum.json');if(!cr.ok)throw Error('Curriculum unavailable');{curriculum=await cr.json();if(JSON.stringify(curriculum.years.map(y=>y.year))!==JSON.stringify([3,4,5,6,7,8]))throw Error('Curriculum incomplete');content.units.push(...curriculum.units);content.nodes.push(...curriculum.nodes);cards.push(...curriculum.cards);visuals.push(...curriculum.visuals);}try{const ar=await fetch('./item-archive.json');content.retiredItems=ar.ok?(await ar.json()).retiredItems||[]:[];}catch{content.retiredItems=[];}let loaded;try{loaded=loadState(localStorage,content);state=loaded.state||loaded;savedRaw=localStorage.getItem(STORAGE_KEY);if(loaded.error||loaded.errors?.length){writeBlocked=true;storageError='Saved progress could not be read. The original data is kept safely. Export it, or import a valid backup in 家长中心.';}}catch{state=createInitialState();storageError='This browser cannot save progress. Keep the tab open and use a backup.';}if(!state?.children)state=createInitialState();state={...state,children:state.children.map(c=>c.id==='B'&&c.age===null?{...c,age:6}:c)};loadSheets();render();
 try{const INTRO_KEY='fern-maths.intro.v1',day=today();if(!navigator.webdriver&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&localStorage.getItem(INTRO_KEY)!==day){localStorage.setItem(INTRO_KEY,day);showIntro();}}catch{}
 if('serviceWorker' in navigator){try{await navigator.serviceWorker.register('./sw.js');await navigator.serviceWorker.ready;const markOffline=()=>{offlineReady=true;const e=document.getElementById('offline-status');if(e)e.textContent='Ready for offline learning';};if(navigator.serviceWorker.controller)markOffline();navigator.serviceWorker.addEventListener('controllerchange',markOffline);}catch{}}
 try{const ctx=document.modelContext;if(ctx?.registerTool){const abort=new AbortController();addEventListener('pagehide',()=>abort.abort(),{once:true});await ctx.registerTool({name:'list_maths_lessons',title:'List maths lessons',description:'Read the selected learner’s available lessons and learning evidence. Does not submit answers.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('No arguments expected');return {learner:state.activeChildId,lessons:lessons().map(l=>({id:l.id,title:l.title_en,status:mastered(l).status}))};}},{signal:abort.signal});await ctx.registerTool({name:'open_maths_lesson',title:'Open a maths lesson',description:'Open a knowledge card for the currently selected learner. Does not answer questions or record mastery.',inputSchema:{type:'object',properties:{lessonId:{type:'string'}},required:['lessonId'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='lessonId')||!lessons().some(l=>l.id===input.lessonId))throw Error('Choose a lesson for the current learner');openKnowledge(input.lessonId);return {opened:input.lessonId};}},{signal:abort.signal});}}catch{console.warn('Optional browser tools are unavailable.');}
 }catch(e){app.innerHTML=`<main class="panel" style="margin:3rem"><h1>We couldn’t open your maths space.</h1><p>Please reconnect and reload this page. Your saved progress has not been deleted.</p><button class="primary" onclick="location.reload()">Try again</button></main>`;console.error(e);}}
addEventListener('storage',e=>{if(e.key===STORAGE_KEY||e.key===SHEET_KEY||e.key===null){writeBlocked=true;storageError='Progress changed in another tab. Reload this page before continuing.';render();}});
init();
